-- =====================================================================
-- carga_dados.sql - Carga inicial do OLTP (Concessionaria de Veiculos)
-- Integrante 4 - Engenheiro de ETL
--
-- Origem: exportacao (pg_dump --data-only --column-inserts) dos dados
-- gerados por carga/CargaDados.java. A classe usa semente fixa, entao
-- este script reproduz exatamente os mesmos registros da carga Java:
--   5 lojas, 34 funcionarios, 200 clientes, 156 documentos (CNH),
--   7 marcas, 32 modelos, 15 servicos, 993 veiculos,
--   2.000 vendas (jan/2024 a out/2026) e 5.015 itens de venda.
--
-- Pre-requisito: banco "concessionaria" com as tabelas criadas por
-- database/oltp/schema-OLTP.sql.
--
-- Como executar (na ordem):
--   psql -U postgres -d concessionaria -f database/oltp/schema-OLTP.sql
--   psql -U postgres -d concessionaria -f database/oltp/carga_dados.sql
--   (ou abrir cada arquivo no Query Tool do pgAdmin e executar)
--
-- O script apaga os dados atuais (como faz a CargaDados) e roda numa
-- unica transacao: se algo falhar, nada fica pela metade.
-- =====================================================================

BEGIN;

TRUNCATE TABLE public.item_venda, public.venda, public.documento_cliente,
  public.veiculo, public.servico, public.modelo, public.marca,
  public.cliente, public.funcionario, public.pessoa, public.loja
  RESTART IDENTITY CASCADE;

